CREATE TABLE IF NOT EXISTS {schema}.buy_orders (id {uuid} PRIMARY KEY, market_name {keyed} NOT NULL REFERENCES {schema}.markets(name), buyer {uuid} NOT NULL, material {keyed} NOT NULL, template_fingerprint {keyed}, quantity {integer} NOT NULL CHECK (quantity > 0), quantity_remaining {integer} NOT NULL CHECK (quantity_remaining >= 0), unit_price {numeric} NOT NULL CHECK (unit_price > 0), escrow_reserved {numeric} NOT NULL CHECK (escrow_reserved >= 0), status {status} NOT NULL CHECK (status IN ('CREATING', 'OPEN', 'FILLED', 'CANCELED', 'EXPIRED', 'VOIDED')), expires_at {ts} NOT NULL, created_at {ts} NOT NULL{defaultNow}, CHECK (quantity_remaining <= quantity))
